package com.powercms.cms.delivery.navigation;
import com.fasterxml.jackson.databind.ObjectMapper;import com.powercms.cms.content.entity.ContentItemEntity;import com.powercms.cms.content.repo.*;import com.powercms.cms.delivery.RenderDatasetCache;import com.powercms.cms.model.repo.ContentTypeRepository;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class NavTreeBuilderTest{@Test void siteScopesFiltersAndLimitsDepth(){var items=mock(ContentItemRepository.class);var versions=mock(ContentVersionRepository.class);var types=mock(ContentTypeRepository.class);UUID site=UUID.randomUUID();ContentItemEntity a=item(site,"/docs","Docs"),b=item(site,"/docs/start","Start"),c=item(site,"/other","Other");when(items.findBySiteIdAndStatus(site,"PUBLISHED")).thenReturn(List.of(a,b,c));when(types.findBySiteIdOrderByCodeAsc(site)).thenReturn(List.of());var folders=mock(com.powercms.cms.sitefolder.repo.SiteFolderRepository.class);when(folders.findBySiteIdOrderBySortOrderAscTitleAsc(site)).thenReturn(List.of());var builder=new NavTreeBuilder(items,versions,types,folders,new RenderDatasetCache(20),new ObjectMapper());var tree=builder.build(site,1,new NavTreeBuilder.Filter(null,"PUBLISHED","/docs",null,Set.of()),true);assertEquals(1,tree.size());assertTrue(tree.get(0).children().isEmpty());verify(items).findBySiteIdAndStatus(site,"PUBLISHED");}@Test void capsDepth(){assertEquals(10,NavTreeBuilder.MAX_DEPTH);}private ContentItemEntity item(UUID s,String p,String t){var x=new ContentItemEntity();x.setId(UUID.randomUUID());x.setSiteId(s);x.setContentTypeId(UUID.randomUUID());x.setRoutePath(p);x.setTitle(t);x.setStatus("PUBLISHED");return x;}}
